import json
import subprocess
from dataclasses import dataclass
from typing import Optional

SCRIPT_PATH = "/opt/travel/jobs/fare_monitor.py"


@dataclass
class FareJobResult:
    ok: bool
    exit_code: int
    drops_found: int
    error: Optional[str] = None


def _parse_output(stdout: str) -> int:
    try:
        payload = json.loads(stdout.strip().splitlines()[-1])
        return int(payload.get("drops", 0))
    except (ValueError, IndexError, AttributeError):
        return 0


def run_fare_alert_job(origin: str, destination: str, depart_date: str, timeout_seconds: int = 120) -> FareJobResult:
    if len(origin) != 3 or len(destination) != 3:
        return FareJobResult(ok=False, exit_code=-1, drops_found=0, error="IATA codes must be 3 letters")
    command = [
        "python3",
        SCRIPT_PATH,
        "--origin",
        origin.upper(),
        "--destination",
        destination.upper(),
        "--date",
        depart_date,
    ]
    try:
        completed = subprocess.run(
            command,
            capture_output=True,
            text=True,
            timeout=timeout_seconds,
        )
    except subprocess.TimeoutExpired:
        return FareJobResult(ok=False, exit_code=-1, drops_found=0, error="job timed out")
    except OSError as exc:
        return FareJobResult(ok=False, exit_code=-1, drops_found=0, error=str(exc))
    if completed.returncode != 0:
        return FareJobResult(
            ok=False,
            exit_code=completed.returncode,
            drops_found=0,
            error=completed.stderr.strip()[:500],
        )
    return FareJobResult(
        ok=True,
        exit_code=0,
        drops_found=_parse_output(completed.stdout),
    )

import sqlite3
from langchain_core.tools import tool

DATABASE_PATH = "/var/data/travel/bookings.db"


@tool
def get_booking_itinerary_details(confirmation_code: str) -> dict:
    database_connection = sqlite3.connect(DATABASE_PATH)
    database_connection.row_factory = sqlite3.Row
    booking_row_from_database = database_connection.execute(
        "SELECT id, status FROM bookings WHERE confirmation_code = ?",
        (confirmation_code.upper(),),
    ).fetchone()
    if booking_row_from_database is None:
        database_connection.close()
        return {"found": False}
    list_of_passenger_rows = database_connection.execute(
        "SELECT full_name FROM passengers WHERE booking_id = ?",
        (booking_row_from_database["id"],),
    ).fetchall()
    list_of_flight_segment_rows = database_connection.execute(
        "SELECT flight_number, origin, destination, departs_at FROM segments "
        "WHERE booking_id = ? ORDER BY departs_at",
        (booking_row_from_database["id"],),
    ).fetchall()
    database_connection.close()
    return {
        "found": True,
        "status": booking_row_from_database["status"],
        "passengers": [row["full_name"] for row in list_of_passenger_rows],
        "segments": [dict(row) for row in list_of_flight_segment_rows],
    }

import sqlite3
from langchain_core.tools import tool

DATABASE_PATH = "/var/data/travel/trips.db"


@tool
def move_booking_to_new_trip(confirmation_code: str, target_trip_id: int, new_label: str = "") -> dict:
    if not confirmation_code or not confirmation_code.strip():
        return {"success": False, "error": "confirmation_code is required"}
    if target_trip_id <= 0:
        return {"success": False, "error": "target_trip_id must be positive"}
    if len(new_label) > 80:
        return {"success": False, "error": "new_label too long"}
    connection = sqlite3.connect(DATABASE_PATH)
    booking = connection.execute(
        "SELECT id, trip_id FROM trip_bookings WHERE confirmation_code = ?",
        (confirmation_code.strip().upper(),),
    ).fetchone()
    if booking is None:
        connection.close()
        return {"success": False, "error": "booking not found"}
    if booking[1] == target_trip_id:
        connection.close()
        return {"success": False, "error": "booking already in that trip"}
    trip = connection.execute("SELECT id FROM trips WHERE id = ?", (target_trip_id,)).fetchone()
    if trip is None:
        connection.close()
        return {"success": False, "error": "target trip not found"}
    if new_label.strip():
        connection.execute(
            "UPDATE trip_bookings SET trip_id = ?, label = ? WHERE id = ?",
            (target_trip_id, new_label.strip(), booking[0]),
        )
    else:
        connection.execute(
            "UPDATE trip_bookings SET trip_id = ? WHERE id = ?",
            (target_trip_id, booking[0]),
        )
    connection.commit()
    connection.close()
    return {"success": True, "booking_id": booking[0], "from_trip": booking[1], "to_trip": target_trip_id}
